class Solution {
    public int[][] flipAndInvertImage(int[][] image){
        for(int[] row:image)for(int left=0,right=row.length-1;left<=right;left++,right--){
            int first=row[left],second=row[right];
            row[left]=second^1;
            row[right]=first^1;
        }
        return image;
    }
}

code.kotlin:
class Solution {
    fun flipAndInvertImage(image:Array<IntArray>):Array<IntArray>{
        for(row in image){
            var left=0;
            var right=row.lastIndex;
            while(left<=right){
                val first=row[left];
                val second=row[right];
                row[left]=second xor 1;
                row[right]=first xor 1;
                left++;
                right--
            }
        };
        return image
    }
}

